error_handling.code:
try {
  int result = 10 ~/ 0;
} on UnsupportedError catch (e) {
  print('Cannot divide by zero: $e');
} catch (e, stackTrace) {
  print('Unknown error: $e');
} finally {
  print('Cleanup');
}

